-- The snapshots TypeScript publishes (regenerated by src/lua/wireFixtures.test.ts),
-- fed to the real Lua parsers.
package.path='frontend/lua/?.lua;'..package.path
local function font()
  return {getWidth=function(_,s) return #tostring(s)*8 end,getHeight=function() return 20 end,setFilter=function() end,
    getWrap=function(_,s) return #tostring(s)*8,{tostring(s)} end}
end
love={math={random=function() return 0.5 end},graphics={newFont=function() return font() end},keyboard={isDown=function() return false end},filesystem={getInfo=function() return nil end}}
local Card=require('ui.card')
Card.rebuild=function(self) self.texture={release=function() end} end
local T=require('ui.theme')
T.font=function() return font() end
local Simulator=require('ui.simulator')
local Library=require('ui.library')
local Builder=require('ui.builder')

local function fixture(name)
  local f=assert(io.open('frontend/lua/tests/fixtures/'..name,'rb'))
  local raw=f:read('*a');f:close()
  return (raw:gsub('\n$',''))
end
local function check(ok,message) if not ok then error(message,2) end end
local function find(list,keep) for _,x in ipairs(list) do if keep(x) then return x end end end
local function count(list,keep) local n=0;for _,x in ipairs(list) do if keep(x) then n=n+1 end end;return n end

local said={}
local sim=Simulator.new({command=function() end,announce=function(t) said[#said+1]=t end,feedback=function() end,settings=function() end,jiggle=function() end})
sim:layout(1280,800);sim:open(false)
sim:sync(fixture('sim_snapshot.txt'))
check(sim.phase=='ready' and sim.you=='Ash' and sim.opponent=='Misty','Header names the players')
check(sim.turn==1 and sim.gamePhase=='turn:action' and sim.title=='Your turn','Header carries the turn and phase')
check(said[#said]=='Your turn.' and sim.messageSerial=='0' and sim.warning=='','Header carries the announcement, refusal serial and warning')
check(sim.viewerSeat=='p1' and sim.activePlayer=='you' and sim.waiting=='you','Header carries the seats')
check(sim.turnCount==1 and sim.matchId=='100' and sim.shuffled=='','Header carries the history and match id')
check(not sim.allow.energy and not sim.allow.supporter and not sim.allow.retreated and not sim.allow.partial,'Nothing used yet this turn')
check(sim.mode=='local' and sim.flags.undo and sim.flags.concede,'Lifecycle row parsed')

local items=sim.items
check(sim.sides.you.hand==count(items,function(i) return i.owner=='you' and i.zone=='hand' end),'Own hand count matches its cards')
check(sim.sides.opponent.hand==count(items,function(i) return i.owner=='opponent' and i.zone=='hand' and i.hidden end),'Opponent hand is face down')
check(sim.sides.you.prizes==6 and sim.sides.opponent.prizes==6,'Six Prize cards each')

local stadium=find(items,function(i) return i.zone=='stadium' end)
check(stadium and stadium.owner=='global' and stadium.name=='Beach Court' and stadium.cardId=='sv01-167','Stadium in play')
check(stadium.category=='Trainer' and stadium.trainerType=='Stadium' and not stadium.hidden and not stadium.draggable,'Stadium is a public Trainer')
check(stadium.hp==nil and stadium.damage==0 and #stadium.energies==0 and #stadium.toolCards==0 and stadium.tools==0,'Stadium carries no battle state')
check(stadium.displayIndex==0 and stadium.index==0,'Stadium sits in its one slot')
check(sim.byUid['global:'..stadium.id],'Stadium placed on the table')

local active=find(items,function(i) return i.owner=='you' and i.zone=='active' end)
check(active.name=='fix-attacker' and active.hp==120 and active.damage==0 and active.types=='Fire','Own Active parsed')
check(#active.energyCards==2 and active.energyCards[1].cardId=='fix-energy' and active.energyCards[1].kind=='Colorless','Attached Energy cards parsed')
check(active.tools==1 and active.toolCards[1].cardId=='fix-tool','Attached Tool parsed')
local foe=find(items,function(i) return i.owner=='opponent' and i.zone=='active' end)
check(foe.hp==120 and foe.damage==40 and #foe.energyCards==0 and foe.tools==0,'Opponent Active carries its damage')
for _,i in ipairs(items) do
  if i.owner=='you' and i.zone=='hand' then check(i.displayIndex==i.index and i.draggable,'Hand card '..i.id..' keeps its order and drags') end
end

check(sim.info['sv01-167'].name=='Beach Court' and sim.info['sv01-167'].effect:find('Retreat Cost'),'Stadium text parsed')
check(sim.info['fix-attacker'].hp=='120' and sim.info['fix-attacker'].attacks:find('Flame'),'Pokemon text parsed')
check(sim.info['fix-energy'].energyType=='Normal' and sim.info['fix-energy'].types=='Colorless','Energy text parsed')

local play=sim.cardActions['nest-ball'][1]
check(play.label=='Play' and not play.disabled and not play.hasCost,'Nest Ball can be played')
local flame=find(sim.cardActions[active.id],function(a) return a.label=='Flame' end)
check(flame.hasCost and flame.damage=='60' and flame.cost[1]=='Fire' and flame.cost[2]=='Colorless','Attack button parsed')
local endTurn=find(sim.actions,function(a) return a.label=='End turn' end)
check(endTurn.slot=='primary' and not endTurn.disabled and endTurn.colour==T.red,'Sidebar parsed')
check(sim.menu==nil,'No prompt on the open table')

sim:sync(fixture('sim_prompt.txt'))
check(sim.gamePhase=='effect:choose' and sim.hint:find('Search your deck'),'Prompt header parsed')
check(said[#said]=='Ash: played Nest Ball.','A played card is announced, got '..tostring(said[#said]))
-- The tray says the prompt's instruction once, as it opens.
sim:update(1/60,1,-1000,-1000,true)
check(said[#said]:find('^Search your deck for a Basic Pokémon onto your Bench%. %d+ cards?%.$'),'The tray opens with its instruction, got '..tostring(said[#said]))
check(sim.menu and sim.menu.kind=='cards' and sim.menu.mandatory,'Search prompt is a mandatory card menu')
check(#sim.menu.options>0 and #sim.menu.footer==3,'Prompt options and footer parsed')
for _,o in ipairs(sim.menu.options) do check(o.uid~='' and o.cardId~='' and o.label~='' and not o.disabled,'Option '..o.token..' names a card') end
check(sim.menu.footer[1].label=='0/1','Footer counts the picks')
check(next(sim.cardActions)==nil,'Card buttons hide behind the prompt')
check(find(sim.items,function(i) return i.id=='nest-ball' end).zone=='discard' and sim.sides.you.discard==1,'Played Item went to the discard')
check(find(sim.items,function(i) return i.zone=='stadium' end).name=='Beach Court','Stadium stays in play')
print('PASS: simulator table and prompt snapshots')

local library=Library.new({command=function() end,announce=function() end,feedback=function() end})
library:layout(1280,800)
library:sync(fixture('library_snapshot.txt'))
check(library.phase=='ready' and not library.busy and library.sort=='name-asc' and library.query=='','Library header parsed')
check(library.page==1 and library.pages==1 and library.total==3,'Library paging parsed')
local names={};for i,d in ipairs(library.items) do names[i]=d.name end
check(table.concat(names,',')=='Fire Rush,Water Wall,Zap Zone','Decks listed in order')
check(library.items[1].count==60 and library.items[1].tint==20 and not library.items[1].illegal,'Legal deck parsed')
check(library.items[2].count==42 and library.items[2].illegal,'Illegal deck flagged')
check(not library.items[3].illegal,'Unchecked deck carries no alert')
print('PASS: library snapshot')

local builder=Builder.new({command=function() end,announce=function() end,feedback=function() end})
builder:layout(1280,800)
builder:sync(fixture('builder_snapshot.txt'))
check(builder.phase=='ready' and builder.name=='Electric Dreams' and builder.format=='standard','Builder header parsed')
check(builder.page==1 and builder.pages==1 and builder.total==2 and builder.count==6 and not builder.busy,'Builder counts parsed')
check(builder.selected=='sv01-050' and not builder.importing and not builder.dirty,'Builder state parsed')
local pikachu,ball=builder.items[1],builder.items[2]
check(#builder.items==2 and pikachu.name=='Pikachu' and ball.name=='Nest Ball','Catalog results parsed')
check(pikachu.quantity==4 and pikachu.remaining==0 and pikachu.hp=='60' and pikachu.mark=='G' and pikachu.number=='12' and pikachu.copyLimit==4,'Catalog card fields parsed')
check(ball.kind=='Trainer' and ball.subtype=='Item' and ball.quantity==2 and ball.remaining==2 and ball.hp=='','Trainer result parsed')
check(#builder.deck==2 and builder.selectedItem.name=='Pikachu','Deck list and selection parsed')
check(builder.selectedItem.gaps=='ability,attack' and pikachu.gaps=='ability,attack' and ball.gaps=='','Simulation gaps parsed')
check(builder.validation:find('more cards') and builder.groups[1]=='4' and builder.groups[2]=='2' and builder.groups[3]=='0','Validation parsed')
local legal=find(builder.options,function(o) return o.key=='legalOnly' end)
check(legal.label=='Legal cards only' and legal.value=='On' and legal.count==2,'Filter option parsed')
check(builder.fields.sort=='name' and builder.fields.query=='','Filter fields parsed')
print('PASS: builder snapshot')

builder:sync(fixture('builder_pending_snapshot.txt'))
local loading=builder.deck[3]
check(#builder.deck==3 and builder.count==9,'A loading entry stays in the deck and its count')
check(loading.id=='sv01-999' and loading.name=='Loading card...' and loading.quantity==3 and loading.pending,'Loading entry parsed')
check(not builder.deck[1].pending and builder.validation=='Loading cards...','Loading verdict parsed')
print('PASS: builder loading snapshot')

local Online=require('ui.online')
